import { defineConfig, devices } from "@playwright/test";

// The tests get their own API on port 4010, with fresh seed data,
// so they never touch the data you're using on port 4000.
const API = "http://127.0.0.1:4010";

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? [["html", { open: "never" }], ["github"]] : [["list"], ["html", { open: "never" }]],
  use: {
    baseURL: "http://localhost:4173",
    trace: "on-first-retry",
  },
  projects: [
    { name: "setup", testMatch: /.*\.setup\.ts/ },
    {
      name: "chromium",
      use: { ...devices["Desktop Chrome"] },
      dependencies: ["setup"],
    },
  ],
  webServer: [
    {
      command: "node ../trailhead-api/server.mjs",
      url: `${API}/v1/products`,
      env: { PORT: "4010", TRAILHEAD_TEST: "1" },
      reuseExistingServer: !process.env.CI,
    },
    {
      command: "npm run build && npm run preview -- --port 4173 --strictPort",
      url: "http://localhost:4173",
      // Build against /v1, not the production API in .env.production,
      // and point the preview server's proxy at the test API.
      env: { VITE_API_URL: "/v1", API_URL: API },
      reuseExistingServer: !process.env.CI,
    },
  ],
});

import { expect, test } from "@playwright/test";

test("a guest's cart moves to their account when they log in", async ({ page }) => {
  await page.goto("/products/storm-shell-jacket");
  await page.getByLabel("Quantity").fill("2");
  await page.getByRole("button", { name: "Add Storm Shell Jacket to cart" }).click();
  await expect(page.getByRole("link", { name: "Cart (2)" })).toBeVisible();

  await page.getByRole("link", { name: "Log in" }).click();
  await page.getByLabel("Email").fill("ana@example.com");
  await page.getByLabel("Password").fill("trailhead");
  await page.getByRole("button", { name: "Log in" }).click();
  await expect(page.getByText("Hi, Ana")).toBeVisible();

  await page.getByRole("link", { name: "Cart (2)" }).click();
  await expect(page.getByRole("listitem")).toHaveText("Storm Shell Jacket × 2: $438.00");
});

import { expect, test } from "@playwright/test";

test("shows an error when the products API fails", async ({ page }) => {
  await page.route("**/v1/products*", (route) =>
    route.fulfill({ status: 500, contentType: "application/problem+json", body: "{}" }),
  );
  await page.goto("/products");

  // TanStack Query retries three times, waiting 1, 2, and 4 seconds, before it gives up.
  await expect(page.getByRole("alert")).toHaveText("Couldn't load products.", { timeout: 10_000 });
});

test("shows a loading message while products load", async ({ page }) => {
  await page.route("**/v1/products*", async (route) => {
    await new Promise((resolve) => setTimeout(resolve, 1_000));
    await route.continue();
  });
  await page.goto("/products");

  await expect(page.getByRole("status")).toHaveText("Loading products…");
  await expect(page.getByRole("list", { name: "Products" })).toBeVisible();
});

test("searching asks the API once, after typing stops", async ({ page }) => {
  await page.goto("/products");
  await expect(page.getByRole("list", { name: "Products" })).toBeVisible();

  const search = page.waitForResponse((response) => response.url().includes("q=tent"));
  await page.getByLabel("Search").pressSequentially("tent");
  const response = await search;

  expect(response.status()).toBe(200);
  await expect(page.getByRole("listitem")).toHaveCount(3);
});

import { expect, test as setup } from "@playwright/test";

const SAM = "e2e/.auth/sam.json";

setup("log in as Sam", async ({ page, request }) => {
  // Start from the seed data, once, before any test runs.
  await request.post("http://127.0.0.1:4010/__reset");

  await page.goto("/login");
  await page.getByLabel("Email").fill("sam@example.com");
  await page.getByLabel("Password").fill("trailhead");
  await page.getByRole("button", { name: "Log in" }).click();

  await expect(page.getByText("Hi, Sam")).toBeVisible();
  await page.context().storageState({ path: SAM });
});

